import re
from datetime import date

def is_date(text):
    m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", text)
    if not m:
        return False
    try:
        date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return False
    return True

for text in ["2026-03-01", "2026-13-45", "26-3-1"]:
    print(text, is_date(text))

